import{_ as i,r as t,o as r,c as d,e as a,a as n,s as l}from"./chunks/framework.CXcwiNg-.js";const w=JSON.parse('{"title":"Dashboard & Statistics - October CMS User Guide","titleTemplate":false,"description":"Customize your dashboard and generate some statistics","frontmatter":{"subtitle":"Customize your dashboard and generate some statistics"},"headers":[{"level":2,"title":"Edit the Dashboard","slug":"edit-the-dashboard","link":"#edit-the-dashboard","children":[]},{"level":2,"title":"Remove a Widget","slug":"remove-a-widget","link":"#remove-a-widget","children":[]},{"level":2,"title":"Reset the Layout","slug":"reset-the-layout","link":"#reset-the-layout","children":[]},{"level":2,"title":"Add Traffic Statistics","slug":"add-traffic-statistics","link":"#add-traffic-statistics","children":[]},{"level":2,"title":"Next Steps","slug":"next-steps","link":"#next-steps","children":[]}],"relativePath":"user-guide/quickstart/backend/dashboard.md","filePath":"user-guide/quickstart/backend/dashboard.md"}'),h={name:"user-guide/quickstart/backend/dashboard.md"};function c(g,e,u,p,m,f){const s=t("pre-heading"),o=t("post-heading");return r(),d("div",null,[a(s),e[0]||(e[0]=n("h1",null,"Dashboard & Statistics",-1)),a(o),e[1]||(e[1]=l('<p>The dashboard is the first thing you see after logging in. Right now it shows a couple of default widgets. Let&#39;s make it your own and give it some real data to display.</p><h2 id="edit-the-dashboard"><a href="#edit-the-dashboard" class="header-anchor">#</a> Edit the Dashboard</h2><p>The dashboard ships with a <strong>Welcome</strong> widget and a <strong>System status</strong> widget. To make changes, you first switch the dashboard into edit mode:</p><ol><li>Click the pencil icon next to the dashboard name and select <strong>Edit Dashboard</strong> from the menu.</li><li>The dashboard enters edit mode, where you can add, configure, move, and remove widgets.</li></ol><p>Try rearranging the widgets by dragging one to a new position. You can also click <strong>Add Widget</strong> in a row to add a new widget, or <strong>Add Row</strong> to start a new row.</p><h2 id="remove-a-widget"><a href="#remove-a-widget" class="header-anchor">#</a> Remove a Widget</h2><p>Let&#39;s clean up by removing the Welcome widget. You won&#39;t need it once you know your way around.</p><ol><li>While in edit mode, click the menu icon on the <strong>Welcome</strong> widget.</li><li>Select <strong>Delete</strong> from the menu.</li></ol><p>The widget disappears. Don&#39;t worry, removing a widget doesn&#39;t delete any data, it just hides the panel.</p><h2 id="reset-the-layout"><a href="#reset-the-layout" class="header-anchor">#</a> Reset the Layout</h2><p>Changed your mind? You can always start over.</p><ol><li>Click the pencil icon next to the dashboard name.</li><li>Select <strong>Reset Layout</strong> from the menu.</li><li>Confirm. Your dashboard returns to the default layout with all the original widgets restored.</li></ol><div class="custom-block aside"><p>Each administrator has their own independent dashboard layout. Resetting yours won&#39;t affect what other admins see.</p></div><h2 id="add-traffic-statistics"><a href="#add-traffic-statistics" class="header-anchor">#</a> Add Traffic Statistics</h2><p>October CMS includes a built-in statistics plugin that tracks page views. Let&#39;s turn it on and generate some sample data.</p><ol><li>Navigate to <strong>Settings → Internal Traffic Statistics</strong> in the main menu.</li><li>Click the <strong>Generate Data</strong> button to create some sample traffic data. This fills the statistics widget with fake page views so you can see how it looks.</li><li>Go back to the <strong>Dashboard</strong> by clicking the Dashboard link in the top menu.</li></ol><p>You should now see a traffic chart on your dashboard. If it doesn&#39;t appear automatically, enter edit mode, click <strong>Add Widget</strong>, and choose the <strong>Traffic Information</strong> data source.</p><div class="custom-block tip"><p>In production, this plugin tracks real visitor traffic automatically, no fake data needed. The statistics you generated here are just for exploring the dashboard during this tutorial.</p></div><h2 id="next-steps"><a href="#next-steps" class="header-anchor">#</a> Next Steps</h2><p>Your dashboard is set up. Next, let&#39;s create another administrator account and explore roles. Continue to <a href="./managing-admins.html">Managing Administrators</a>.</p>',20))])}const y=i(h,[["render",c]]);export{w as __pageData,y as default};
